using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.AppHost.Evaluation;

public class EvaluationTests
{
    [Fact]
    public async Task AppHost_Starts_Successfully()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await using var app = await builder.BuildAsync();
        await app.StartAsync();
        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));
    }

    [Fact]
    public async Task AppHost_Resources_Are_Running()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await using var app = await builder.BuildAsync();
        await app.StartAsync();
        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));

        var resourceNotificationService = app.Services.GetRequiredService<ResourceNotificationService>();
        // Verify the app host reaches a running state without errors
        Assert.NotNull(resourceNotificationService);
    }
}

